//! Excel conformance: replays `fixtures/calc/conformance.json` through [`Engine`] and compares each result with
//! the value Microsoft Excel produced for the same case (`fixtures/reference/calc/conformance-results.json`,
//! generated by `tools/office/calc-oracle.ps1`). CI does not need Excel.
//!
//! Every case must match exactly (numbers bit for bit, text per UTF-16 unit, errors by code) unless it is listed
//! in `fixtures/calc/known-differences.toml` with a reason. A listed case that starts to pass is an error too, so
//! the list can only shrink.

use std::cell::RefCell;
use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::fs;
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::path::PathBuf;
use std::sync::Arc;

use open365_calc::numfmt::{format_value_in, validate_format};
use open365_calc::{Engine, ErrorKind, FormatLocale, Value};
use open365_locale::Locale;
use serde::Deserialize;

#[derive(Debug, Deserialize)]
struct Corpus {
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Case {
    id: String,
    formula: String,
    #[serde(default)]
    cells: BTreeMap<String, CellSpec>,
    #[serde(default)]
    sheet2: BTreeMap<String, CellSpec>,
    at: Option<String>,
    #[serde(default)]
    date1904: bool,
    /// Number format applied to the formula cell; the case then also checks `Range.Text`.
    format: Option<String>,
    /// `"en-GB"`: the case depends on the oracle's system locale and Open365 evaluates it in that locale.
    /// Without it the case must give the same answer in every locale.
    locale: Option<String>,
}

/// The locale a case is evaluated in (en-US unless the case names one); built once per tag.
fn case_locale(case: &Case) -> Arc<FormatLocale> {
    thread_local! {
        static CACHE: RefCell<HashMap<String, Arc<FormatLocale>>> = RefCell::new(HashMap::new());
    }
    let tag = case.locale.as_deref().unwrap_or("en-US").to_owned();
    CACHE.with(|c| {
        c.borrow_mut()
            .entry(tag.clone())
            .or_insert_with(|| {
                let locale = Locale::from_bcp47(&tag).expect("locale tag");
                Arc::new(FormatLocale::new(&locale))
            })
            .clone()
    })
}

#[derive(Debug, Deserialize)]
#[serde(untagged)]
enum CellSpec {
    Bool(bool),
    Number(f64),
    Text(String),
    Error { err: String },
    Formula { f: String },
}

#[derive(Debug, Deserialize)]
struct Reference {
    results: Vec<Expected>,
}

#[derive(Debug, Deserialize)]
struct Expected {
    id: String,
    kind: String,
    value: Option<serde_json::Value>,
    /// `Range.Text` of the formula cell.
    text: Option<String>,
    /// For rejected cases: `NumberFormat` when Excel refused the format code rather than the formula.
    hresult: Option<String>,
}

#[derive(Debug, Deserialize)]
struct KnownFile {
    #[serde(default)]
    difference: Vec<Known>,
}

#[derive(Debug, Deserialize)]
struct Known {
    id: String,
    reason: String,
}

fn fixture(rel: &str) -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../fixtures")
        .join(rel)
}

/// `"C12"` to 1-based `(row, col)`.
fn parse_addr(addr: &str) -> (u32, u32) {
    let letters = addr.bytes().take_while(u8::is_ascii_alphabetic).count();
    let col = addr[..letters].bytes().fold(0u32, |acc, b| {
        acc * 26 + u32::from(b.to_ascii_uppercase() - b'A' + 1)
    });
    let row: u32 = addr[letters..].parse().expect("row number");
    (row, col)
}

fn load_cells(engine: &mut Engine, sheet: &str, cells: &BTreeMap<String, CellSpec>) {
    for (addr, spec) in cells {
        let (row, col) = parse_addr(addr);
        match spec {
            CellSpec::Number(n) => engine.set_value(sheet, row, col, Value::Number(*n)),
            CellSpec::Text(t) => engine.set_value(sheet, row, col, Value::Text(t.clone())),
            CellSpec::Bool(b) => engine.set_value(sheet, row, col, Value::Bool(*b)),
            CellSpec::Error { err } => {
                let kind = ErrorKind::parse(err).expect("known error literal");
                engine.set_value(sheet, row, col, Value::Error(kind));
            }
            CellSpec::Formula { f } => engine
                .set_formula(sheet, row, col, f)
                .expect("input formula parses"),
        }
    }
}

/// What Open365 produced for a case.
#[derive(Debug)]
enum Outcome {
    Rejected,
    Value(Value),
}

fn run_case(case: &Case) -> Outcome {
    let mut engine = Engine::new();
    engine.set_date1904(case.date1904);
    engine.set_format_locale(case_locale(case));
    engine.add_sheet("Sheet1");
    engine.add_sheet("Sheet2");
    load_cells(&mut engine, "Sheet1", &case.cells);
    load_cells(&mut engine, "Sheet2", &case.sheet2);
    let (row, col) = parse_addr(case.at.as_deref().unwrap_or("J20"));
    if engine
        .set_formula("Sheet1", row, col, &case.formula)
        .is_err()
    {
        return Outcome::Rejected;
    }
    engine.recalc_all();
    Outcome::Value(engine.get("Sheet1", row, col))
}

fn show_value(v: &Value) -> String {
    match v {
        Value::Number(n) => format!("number {n:?}"),
        Value::Text(t) => format!("text {t:?}"),
        Value::Bool(b) => format!("bool {b}"),
        Value::Error(e) => format!("error {e}"),
        Value::Empty => "blank".to_owned(),
        Value::Array(_) => "array".to_owned(),
    }
}

fn show_expected(e: &Expected) -> String {
    match (&e.value, e.kind.as_str()) {
        (Some(serde_json::Value::Number(n)), "number") => format!("number {n}"),
        (Some(serde_json::Value::String(s)), "text") => format!("text {s:?}"),
        (Some(v), kind) => format!("{kind} {v}"),
        (None, kind) => kind.to_owned(),
    }
}

/// `None` when Open365 agrees with Excel, otherwise a description of the mismatch.
fn compare(expected: &Expected, outcome: &Outcome) -> Option<String> {
    let describe = |actual: String| {
        Some(format!(
            "Excel: {}  Open365: {actual}",
            show_expected(expected)
        ))
    };
    match (expected.kind.as_str(), outcome) {
        // Excel refuses to accept the formula. Open365 passes if its parser refuses too or the formula
        // evaluates to an error value (a loader must keep such a cell rather than fail the whole file).
        ("rejected", Outcome::Rejected) => None,
        ("rejected", Outcome::Value(Value::Error(_))) => None,
        (_, Outcome::Rejected) => describe("parse error".to_owned()),
        (kind, Outcome::Value(actual)) => {
            let ok = match (kind, actual, expected.value.as_ref()) {
                ("number", Value::Number(a), Some(serde_json::Value::Number(e))) => {
                    e.as_f64().is_some_and(|e| e == *a)
                }
                ("text", Value::Text(a), Some(serde_json::Value::String(e))) => a == e,
                ("bool", Value::Bool(a), Some(serde_json::Value::Bool(e))) => a == e,
                ("error", Value::Error(a), Some(serde_json::Value::String(e))) => {
                    // The oracle names only the classic errors; others are `#UNKNOWN(code)` with the name in `Range.Text`.
                    let name = match (e.starts_with("#UNKNOWN("), expected.text.as_deref()) {
                        (true, Some(t)) => t,
                        _ => e.as_str(),
                    };
                    a.as_str() == name
                }
                _ => false,
            };
            if ok {
                None
            } else {
                describe(show_value(actual))
            }
        }
    }
}

/// For a case with a number format: the displayed text must equal `Range.Text`, and Excel refusing the format
/// code must match Open365 refusing it.
fn compare_display(case: &Case, expected: &Expected, outcome: &Outcome) -> Option<String> {
    let format = case.format.as_deref()?;
    if expected.kind == "rejected" {
        if expected.hresult.as_deref() != Some("NumberFormat") {
            return None;
        }
        return validate_format(format)
            .is_ok()
            .then(|| format!("Excel refuses the format {format:?}; Open365 accepts it"));
    }
    let Outcome::Value(value) = outcome else {
        return None;
    };
    let shown = format_value_in(value, format, case.date1904, &case_locale(case));
    let want = expected.text.as_deref().unwrap_or_default();
    (shown != want)
        .then(|| format!("Range.Text: Excel {want:?}  Open365 {shown:?}  (format {format:?})"))
}

fn group_of(id: &str) -> &str {
    id.split('.').next().unwrap_or(id)
}

#[test]
fn matches_excel() {
    let corpus: Corpus = serde_json::from_str(
        &fs::read_to_string(fixture("calc/conformance.json")).expect("corpus"),
    )
    .expect("corpus json");
    let reference: Reference = serde_json::from_str(
        &fs::read_to_string(fixture("reference/calc/conformance-results.json")).expect("results"),
    )
    .expect("results json");
    let known: KnownFile = toml::from_str(
        &fs::read_to_string(fixture("calc/known-differences.toml")).expect("known differences"),
    )
    .expect("known-differences.toml");

    // Every corpus case needs an Excel answer (a case without one would pass unchecked), and every stored
    // answer must belong to a case. Order does not matter.
    let mut answers: BTreeMap<&str, &Expected> = BTreeMap::new();
    for expected in &reference.results {
        assert!(
            answers.insert(expected.id.as_str(), expected).is_none(),
            "duplicate Excel result for {}",
            expected.id
        );
    }
    let corpus_ids: BTreeSet<&str> = corpus.cases.iter().map(|c| c.id.as_str()).collect();
    assert_eq!(
        corpus_ids.len(),
        corpus.cases.len(),
        "duplicate case ids in the corpus"
    );
    let missing: Vec<&str> = corpus
        .cases
        .iter()
        .filter(|c| !answers.contains_key(c.id.as_str()))
        .map(|c| c.id.as_str())
        .collect();
    assert!(
        missing.is_empty(),
        "{} corpus cases have no Excel result; run tools/office/calc-oracle.ps1 -Update:
  {}",
        missing.len(),
        missing.join(
            "
  "
        )
    );
    let orphans: Vec<&str> = answers
        .keys()
        .filter(|id| !corpus_ids.contains(*id))
        .copied()
        .collect();
    assert!(
        orphans.is_empty(),
        "Excel results without a corpus case: {}",
        orphans.join(", ")
    );
    let known_ids: BTreeMap<&str, &str> = known
        .difference
        .iter()
        .map(|k| (k.id.as_str(), k.reason.as_str()))
        .collect();
    assert_eq!(
        known_ids.len(),
        known.difference.len(),
        "duplicate ids in known-differences.toml"
    );
    for id in known_ids.keys() {
        assert!(
            corpus_ids.contains(id),
            "known-differences.toml lists unknown case {id}"
        );
    }

    let mut per_group: BTreeMap<String, (u32, u32, u32)> = BTreeMap::new(); // pass, known, fail
    let mut unexpected = Vec::new();
    let mut stale = Vec::new();
    let (mut pass, mut known_diff) = (0u32, 0u32);

    for case in &corpus.cases {
        let expected = answers[case.id.as_str()];
        assert!(
            matches!(
                expected.kind.as_str(),
                "number" | "text" | "bool" | "error" | "rejected"
            ),
            "{}: Excel result kind {:?} is not a usable answer",
            case.id,
            expected.kind
        );
        let outcome = catch_unwind(AssertUnwindSafe(|| run_case(case)));
        let mismatch = match &outcome {
            Ok(outcome) => (if case.format.is_some()
                && expected.kind == "rejected"
                && expected.hresult.as_deref() == Some("NumberFormat")
            {
                None
            } else {
                compare(expected, outcome)
            })
            .or_else(|| {
                catch_unwind(AssertUnwindSafe(|| {
                    compare_display(case, expected, outcome)
                }))
                .unwrap_or_else(|_| Some("Range.Text: panic".to_owned()))
            }),
            Err(_) => Some(format!(
                "Excel: {}  Open365: panic",
                show_expected(expected)
            )),
        };
        let slot = per_group.entry(group_of(&case.id).to_owned()).or_default();
        match (mismatch, known_ids.get(case.id.as_str())) {
            (None, None) => {
                pass += 1;
                slot.0 += 1;
            }
            (None, Some(_)) => {
                stale.push(case.id.clone());
                slot.0 += 1;
            }
            (Some(_), Some(_)) => {
                known_diff += 1;
                slot.1 += 1;
            }
            (Some(detail), None) => {
                slot.2 += 1;
                unexpected.push(format!(
                    "{}  {}\n    formula: {}\n    {detail}",
                    case.id,
                    case.at
                        .as_deref()
                        .map_or(String::new(), |a| format!("(at {a})")),
                    case.formula
                ));
            }
        }
    }

    println!("excel conformance by function (pass / known difference / unexpected):");
    for (group, (p, k, f)) in &per_group {
        println!("  {group:<16} {p:>5} {k:>5} {f:>5}");
    }
    let total = corpus.cases.len();
    println!(
        "total {total}: {pass} pass, {known_diff} known differences, {} unexpected, pass rate {:.2}%",
        unexpected.len(),
        100.0 * f64::from(pass) / total as f64
    );

    assert!(
        stale.is_empty(),
        "these cases pass now; remove them from fixtures/calc/known-differences.toml:\n  {}",
        stale.join("\n  ")
    );
    assert!(
        unexpected.is_empty(),
        "{} cases differ from Excel and are not in known-differences.toml:\n{}",
        unexpected.len(),
        unexpected.join("\n")
    );
}
